<?php
/** AI cost-origin and project-type governance. PHP 5.6 compatible. */
use App\Core\Auth;
use App\Core\Db;
use App\Services\CostDataEventService;
use App\Services\AiCostDataGovernanceService;
use App\Services\AiProjectTypeService;
use App\Services\AiDailyPipelineService;

require_once __DIR__ . '/../../services/CostDataEventService.php';
require_once __DIR__ . '/../../services/AiCostDataGovernanceService.php';
require_once __DIR__ . '/../../services/AiProjectTypeService.php';
require_once __DIR__ . '/../../services/AiDailyPipelineService.php';

if (!Auth::check() || !Auth::isDevelopmentDepartment()) { http_response_code(403); echo h('접근 권한이 없습니다.'); return; }
$govPdo=null;$govResult=null;try{$govPdo=Db::pdo();}catch(Exception $e){$govResult=array('ok'=>false,'message'=>'DB 연결 상태를 확인할 수 없습니다.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    $token=isset($_POST['_csrf'])?(string)$_POST['_csrf']:'';$action=isset($_POST['action'])?trim((string)$_POST['action']):'';
    if(!csrf_check($token))$govResult=array('ok'=>false,'message'=>'보안 토큰이 올바르지 않습니다.');
    else if(!$govPdo)$govResult=array('ok'=>false,'message'=>'DB 연결 상태를 확인할 수 없습니다.');
    else if($action==='install'){$a=CostDataEventService::installOrUpdate($govPdo);$b=AiDailyPipelineService::installOrUpdate($govPdo);$govResult=array('ok'=>!empty($a['ok'])&&!empty($b['ok']),'message'=>(isset($a['message'])?$a['message']:'').' '.(isset($b['message'])?$b['message']:''));}
    else if($action==='classify_existing')$govResult=AiCostDataGovernanceService::classifyExisting($govPdo);
    else if($action==='review_origin')$govResult=AiCostDataGovernanceService::reviewOrigin($govPdo,isset($_POST['map_id'])?(int)$_POST['map_id']:0,isset($_POST['data_origin'])?$_POST['data_origin']:'UNKNOWN_REVIEW',!empty($_POST['amount_eligible']),!empty($_POST['timing_eligible']),isset($_POST['reason'])?$_POST['reason']:'');
    else if($action==='save_type')$govResult=AiProjectTypeService::saveType($govPdo,$_POST,isset($_POST['reason'])?$_POST['reason']:'');
    else if($action==='assign_project')$govResult=AiProjectTypeService::assignProject($govPdo,isset($_POST['project_id'])?(int)$_POST['project_id']:0,isset($_POST['project_type_id'])?(int)$_POST['project_type_id']:0,isset($_POST['reason'])?$_POST['reason']:'');
    else $govResult=array('ok'=>false,'message'=>'요청값이 올바르지 않습니다.');
}
$govStatus=$govPdo?AiCostDataGovernanceService::status($govPdo):array('total_count'=>0,'unknown_count'=>0,'timing_eligible_count'=>0);$govSchema=$govPdo?AiCostDataGovernanceService::isInstalled($govPdo):false;$govRows=$govSchema?AiCostDataGovernanceService::listMappings($govPdo,array('origin'=>isset($_GET['origin'])?$_GET['origin']:''),1,100):array();$govTypes=$govPdo?AiProjectTypeService::listTypes($govPdo,false):array();$govProjects=array();
if($govPdo){try{$st=$govPdo->query('SELECT id,name FROM cpms_projects ORDER BY name,id LIMIT 1000');if($st){$rows=$st->fetchAll(PDO::FETCH_ASSOC);if(is_array($rows))$govProjects=$rows;}}catch(Exception $e){$govProjects=array();}}
$govOriginLabels=AiCostDataGovernanceService::originLabels();
?>
