  <form method="post" class="gov-form" style="margin-top:14px"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token()); ?>"><input type="hidden" name="action" value="assign_project"><label>현장<select name="project_id" required><option value="">선택</option><?php foreach($govProjects as $project): ?><option value="<?php echo (int)$project['id']; ?>"><?php echo h(trim((string)$project['name'])!==''?$project['name']:'현장정보 확인 필요'); ?></option><?php endforeach; ?></select></label><label>현장유형<select name="project_type_id"><option value="0">미지정</option><?php foreach($govTypes as $type):if(empty($type['is_active']))continue; ?><option value="<?php echo (int)$type['id']; ?>"><?php echo h($type['type_name']); ?></option><?php endforeach; ?></select></label><label>지정사유<input name="reason" required maxlength="500"></label><button>현장유형 지정</button></form>
